create function pg_temp.assert_true(value boolean,message text) returns void language plpgsql as $$begin if value is not true then raise exception 'Assertion: %',message;end if;end$$;
insert into auth.users values('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222');
insert into public.documents(id,user_id,storage_path,storage_bucket,file_size,checksum) values
 ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','11111111-1111-4111-8111-111111111111/files/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa/sealed.pdf','private-test',100,repeat('a',64)),
 ('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','22222222-2222-4222-8222-222222222222','22222222-2222-4222-8222-222222222222/files/bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb/sealed.pdf','private-test',100,repeat('b',64));
set role authenticated;
set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
select public.start_document_ocr('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
select pg_temp.assert_true((select count(*)=1 from public.document_ocr_jobs),'only own job visible');
do $$ begin
  begin perform public.start_document_ocr('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'); raise exception 'accepted duplicate active start';
  exception when raise_exception then if sqlerrm<>'ocr_busy' then raise; end if; end;
end $$;
select pg_temp.assert_true(not public.update_document_ocr('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','ffffffff-ffff-4fff-8fff-ffffffffffff','complete',1,1,'forged',repeat('a',64)),'wrong token cannot publish');
select pg_temp.assert_true(not public.update_document_ocr('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',(select run_token from public.document_ocr_jobs),'complete',1,1,'wrong digest',repeat('b',64)),'checksum mismatch cannot publish');
select pg_temp.assert_true(public.update_document_ocr('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',(select run_token from public.document_ocr_jobs),'progress',1,2),'progress accepted');
select pg_temp.assert_true(not public.update_document_ocr('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',(select run_token from public.document_ocr_jobs),'progress',0,2),'progress cannot regress');
select pg_temp.assert_true(public.update_document_ocr('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',(select run_token from public.document_ocr_jobs),'complete',2,2,'私人文档 OCR searchable fixture',repeat('a',64),null,1),'matching source publishes');
select pg_temp.assert_true((select extracted_text like '%searchable%' and text_extraction_status='completed' from public.documents where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'text stored');
select pg_temp.assert_true((select page_count=2 and empty_pages=1 from public.document_ocr_jobs),'blank page is counted without discarding recognized text');
select pg_temp.assert_true((select text_extraction_method='ocr_local' and text_extraction_engine_version like '%7.0.0%' and text_extraction_model_version like '%1.0.0%' and text_extraction_source_sha256=repeat('a',64) and text_extraction_page_count=2 and text_extraction_empty_pages=1 from public.documents where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'durable provenance recorded');
select pg_temp.assert_true((select content_text like '%私人文档%' from public.search_documents where entity_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'existing search trigger indexes OCR text');
select pg_temp.assert_true(not public.update_document_ocr('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',(select run_token from public.document_ocr_jobs),'complete',1,1,'duplicate',repeat('a',64)),'completed run cannot republish');
set request.jwt.claim.sub='22222222-2222-4222-8222-222222222222';
select pg_temp.assert_true((select count(*)=0 from public.document_ocr_jobs),'other owner cannot read job');
select pg_temp.assert_true((select count(*)=0 from public.search_documents where content_text like '%searchable%'),'other owner cannot read recognized search text');
select pg_temp.assert_true(not public.update_document_ocr('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','ffffffff-ffff-4fff-8fff-ffffffffffff','cancel'),'other owner cannot cancel');
set request.jwt.claim.sub='11111111-1111-4111-8111-111111111111';
select public.start_document_ocr('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
select pg_temp.assert_true(public.update_document_ocr('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',(select run_token from public.document_ocr_jobs),'cancel'),'cancel accepted');
select pg_temp.assert_true((select extracted_text like '%searchable%' from public.documents),'cancel preserves old index');
select pg_temp.assert_true((select text_extraction_source_sha256=repeat('a',64) and text_extraction_page_count=2 and text_extraction_empty_pages=1 from public.documents),'cancel preserves successful provenance');
select public.start_document_ocr('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
reset role;
update public.documents set checksum=repeat('c',64) where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
select pg_temp.assert_true((select extracted_text is null and extracted_character_count=0 and text_extraction_source_sha256 is null and text_extraction_engine_version is null from public.documents where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'source change clears text');
select pg_temp.assert_true((select content_text not like '%searchable%' from public.search_documents where entity_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'source change clears searchable text');
select pg_temp.assert_true((select count(*)=0 from public.document_ocr_jobs),'source change invalidates token');
set role authenticated;
select public.start_document_ocr('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa');
reset role;
update public.documents set archived_at=now() where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
select pg_temp.assert_true((select status='cancelled' from public.document_ocr_jobs),'archiving cancels in-flight work');
select pg_temp.assert_true((select count(*)=0 from public.search_documents where entity_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'archive removes searchable text');
set role authenticated;
select pg_temp.assert_true((select count(*)=0 from public.document_ocr_jobs),'archived jobs hidden');
reset role;
select pg_temp.assert_true(not has_function_privilege('anon','public.start_document_ocr(uuid)','execute'),'anonymous cannot start');
select pg_temp.assert_true(not has_table_privilege('authenticated','public.document_ocr_jobs','insert'),'jobs cannot bypass guarded RPC');
